export function rng(seed){let n=seed>>>0||1;return()=>{n^=n<<13;n^=n>>>17;n^=n<<5;return(n>>>0)/4294967296}}
export function inGhost(x,y,g,eyes=false){const nx=(x-g.x)/g.rx,ny=(y-g.y)/g.ry;const head=ny<-.12&&nx*nx+(ny+.12)**2<.82**2;const body=ny>=-.12&&Math.abs(nx)<.82&&ny<.58+.12*Math.cos(nx*Math.PI*3);if(!head&&!body)return false;if(eyes&&(((nx-.28)**2/.11**2+(ny+.19)**2/.15**2<1)||((nx+.28)**2/.11**2+(ny+.19)**2/.15**2<1)))return false;return true}
export function makeField(seed,previous){const random=rng(seed);let ghost={x:.25+random()*.50,y:.39+random()*.21,rx:.14,ry:.27};if(previous&&(Math.hypot(ghost.x-previous.x,ghost.y-previous.y)<.24||inGhost(previous.x,previous.y,{...ghost,rx:ghost.rx*1.12,ry:ghost.ry*1.10})))ghost.x=previous.x<.5?.78:.22;const dots=Array.from({length:2600},()=>{const x=random(),y=random();return{x,y,p:random()*Math.PI*2,q:random()*Math.PI*2,r:.55+random()*.65,coherent:inGhost(x,y,ghost,true)}});return{ghost,dots}}
export function dotPosition(dot,phase,w,h){const a=dot.coherent?10:1.6;return{x:dot.x*w+Math.sin(phase+(dot.coherent?0:dot.p))*a,y:dot.y*h+Math.cos(phase+(dot.coherent?0:dot.q))*a}}
export function judgeCapture({x,y,ghost,motionMs}){if(![x,y,motionMs].every(Number.isFinite)||x<0||x>1||y<0||y>1)return{accepted:false,reason:'invalid coordinates'};if(motionMs<900)return{accepted:false,reason:'play the record first'};return inGhost(x,y,{...ghost,rx:ghost.rx*1.12,ry:ghost.ry*1.10})?{accepted:true,reason:'ghost captured'}:{accepted:false,reason:'missed the ghost'}}
